package main

import (
	"database/sql"
	"fmt"
	"path/filepath"
	"sync"

	_ "github.com/mattn/go-sqlite3"
)

type Ledger struct {
	db *sql.DB
	mu sync.Mutex
}

type dbRow struct {
	ID      int64
	Key     string
	Account string
	Amount  int
	Status  string
}

func NewLedger(dataDir string) (*Ledger, error) {
	dsn := filepath.Join(dataDir, "ledger.db") + "?_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL"
	db, err := sql.Open("sqlite3", dsn)
	if err != nil {
		return nil, err
	}

	// One connection makes transaction setup simple and avoids SQLITE_BUSY from
	// concurrent connections in this process. The busy timeout also protects
	// against access by an old process during a restart.
	db.SetMaxOpenConns(1)
	if err := db.Ping(); err != nil {
		db.Close()
		return nil, err
	}

	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS transactions (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			key TEXT NOT NULL,
			account TEXT NOT NULL,
			amount INTEGER NOT NULL,
			status TEXT NOT NULL DEFAULT 'pending'
		);
		CREATE TABLE IF NOT EXISTS accounts (
			name TEXT PRIMARY KEY,
			balance INTEGER NOT NULL DEFAULT 0
		);
	`)
	if err != nil {
		db.Close()
		return nil, err
	}

	ledger := &Ledger{db: db}
	if err := ledger.dedupeLegacyTransactions(); err != nil {
		db.Close()
		return nil, err
	}

	// The unique index is the persistent source of idempotency. The cleanup
	// above permits this index to be installed over a database written by the
	// old duplicate-debit implementation.
	_, err = db.Exec(`CREATE UNIQUE INDEX IF NOT EXISTS idx_transactions_key ON transactions(key)`)
	if err != nil {
		db.Close()
		return nil, err
	}
	return ledger, nil
}

func (l *Ledger) Close() error {
	return l.db.Close()
}

// dedupeLegacyTransactions repairs rows written by the old implementation.
// For each key it keeps the first completed transaction, or otherwise the
// first pending transaction. Extra completed rows were erroneous duplicate
// debits, so their amounts are credited back before they are deleted.
func (l *Ledger) dedupeLegacyTransactions() error {
	rows, err := l.db.Query(`SELECT id, key, account, amount, status FROM transactions ORDER BY id`)
	if err != nil {
		return err
	}

	var all []dbRow
	for rows.Next() {
		var row dbRow
		if err := rows.Scan(&row.ID, &row.Key, &row.Account, &row.Amount, &row.Status); err != nil {
			rows.Close()
			return err
		}
		all = append(all, row)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return err
	}
	rows.Close()
	if len(all) == 0 {
		return nil
	}

	canonical := make(map[string]dbRow)
	for _, row := range all {
		keep, ok := canonical[row.Key]
		if !ok {
			canonical[row.Key] = row
			continue
		}
		if keep.Status != "completed" && row.Status == "completed" {
			canonical[row.Key] = row
		}
	}

	tx, err := l.db.Begin()
	if err != nil {
		return err
	}
	committed := false
	defer func() {
		if !committed {
			tx.Rollback()
		}
	}()

	for _, row := range all {
		keep := canonical[row.Key]
		if row.ID == keep.ID {
			continue
		}
		if _, err := tx.Exec(`DELETE FROM transactions WHERE id = ?`, row.ID); err != nil {
			return err
		}
		if row.Status == "completed" {
			_, err = tx.Exec(`
				INSERT INTO accounts(name, balance) VALUES(?, ?)
				ON CONFLICT(name) DO UPDATE SET balance = balance + excluded.balance
			`, row.Account, row.Amount)
			if err != nil {
				return err
			}
		}
	}

	err = tx.Commit()
	committed = err == nil
	return err
}

// Recover completes any durable pending rows left by an older process. Each
// row is re-read and completed inside a single SQLite transaction, so it is
// impossible to apply the account debit without marking the key completed.
func (l *Ledger) Recover() error {
	rows, err := l.db.Query(`SELECT id, key, account, amount FROM transactions WHERE status = 'pending' ORDER BY id`)
	if err != nil {
		return err
	}

	var pending []Transaction
	for rows.Next() {
		var tx Transaction
		if err := rows.Scan(&tx.Key, &tx.Account, &tx.Amount); err != nil {
			rows.Close()
			return err
		}
		tx.Status = "pending"
		pending = append(pending, tx)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return err
	}
	rows.Close()

	for i := range pending {
		if err := l.completePending(&pending[i]); err != nil {
			return err
		}
	}
	return nil
}

// Submit creates and completes a transaction, or returns the already persisted
// transaction for the same key. The account update and status transition are
// committed atomically.
func (l *Ledger) Submit(key, account string, amount int) (*Transaction, error) {
	l.mu.Lock()
	defer l.mu.Unlock()

	dbTx, err := l.db.Begin()
	if err != nil {
		return nil, err
	}
	committed := false
	defer func() {
		if !committed {
			dbTx.Rollback()
		}
	}()

	var existing Transaction
	err = dbTx.QueryRow(`SELECT id, key, account, amount, status FROM transactions WHERE key = ?`, key).
		Scan(&existing.ID, &existing.Key, &existing.Account, &existing.Amount, &existing.Status)
	switch {
	case err == nil:
		if existing.Status != "completed" && existing.Status != "pending" {
			return nil, fmt.Errorf("transaction %q has unknown status %q", key, existing.Status)
		}
		if existing.Status == "pending" {
			if err := debitAndComplete(dbTx, &existing); err != nil {
				return nil, err
			}
		}
	case err == sql.ErrNoRows:
		res, insertErr := dbTx.Exec(
			`INSERT INTO transactions(key, account, amount, status) VALUES(?, ?, ?, 'pending')`,
			key, account, amount,
		)
		if insertErr != nil {
			return nil, insertErr
		}
		id, err := res.LastInsertId()
		if err != nil {
			return nil, err
		}
		existing = Transaction{ID: id, Key: key, Account: account, Amount: amount, Status: "pending"}
		if err := debitAndComplete(dbTx, &existing); err != nil {
			return nil, err
		}
	default:
		return nil, err
	}

	err = dbTx.Commit()
	committed = err == nil
	if err != nil {
		return nil, err
	}
	return &existing, nil
}

func (l *Ledger) completePending(pending *Transaction) error {
	dbTx, err := l.db.Begin()
	if err != nil {
		return err
	}
	committed := false
	defer func() {
		if !committed {
			dbTx.Rollback()
		}
	}()

	var current Transaction
	err = dbTx.QueryRow(`SELECT id, key, account, amount, status FROM transactions WHERE key = ?`, pending.Key).
		Scan(&current.ID, &current.Key, &current.Account, &current.Amount, &current.Status)
	if err != nil {
		return err
	}
	if current.Status == "pending" {
		if err := debitAndComplete(dbTx, &current); err != nil {
			return err
		}
	} else if current.Status != "completed" {
		return fmt.Errorf("transaction %q has unknown status %q", current.Key, current.Status)
	}

	err = dbTx.Commit()
	committed = err == nil
	return err
}

func debitAndComplete(dbTx *sql.Tx, tx *Transaction) error {
	if tx.Status != "pending" {
		return fmt.Errorf("transaction %q is not pending", tx.Key)
	}

	res, err := dbTx.Exec(`UPDATE accounts SET balance = balance - ? WHERE name = ?`, tx.Amount, tx.Account)
	if err != nil {
		return err
	}
	affected, err := res.RowsAffected()
	if err != nil {
		return err
	}
	if affected == 0 {
		if _, err := dbTx.Exec(`INSERT INTO accounts(name, balance) VALUES(?, 0 - ?)`, tx.Account, tx.Amount); err != nil {
			return err
		}
	}

	res, err = dbTx.Exec(`UPDATE transactions SET status = 'completed' WHERE id = ? AND status = 'pending'`, tx.ID)
	if err != nil {
		return err
	}
	affected, err = res.RowsAffected()
	if err != nil {
		return err
	}
	if affected != 1 {
		return fmt.Errorf("transaction %q was not completed atomically", tx.Key)
	}
	tx.Status = "completed"
	return nil
}

func (l *Ledger) GetTransaction(key string) (*Transaction, error) {
	var tx Transaction
	err := l.db.QueryRow(
		`SELECT key, account, amount, status FROM transactions WHERE key = ? ORDER BY id ASC LIMIT 1`, key,
	).Scan(&tx.Key, &tx.Account, &tx.Amount, &tx.Status)
	if err == sql.ErrNoRows {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &tx, nil
}

func (l *Ledger) GetAccount(name string) (int, bool, error) {
	var balance int
	err := l.db.QueryRow(`SELECT balance FROM accounts WHERE name = ?`, name).Scan(&balance)
	if err == sql.ErrNoRows {
		return 0, false, nil
	}
	if err != nil {
		return 0, false, err
	}
	return balance, true, nil
}
EOF

